#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "nussinov.h"

/* RNA bases represented as chars, range is [0,3] */
typedef char base;

#define match(b1, b2) (((b1)+(b2)) == 3 ? 1 : 0)
#define max_score(s1, s2) ((s1 >= s2) ? s1 : s2)

/* Tunable blocking factor for the i-dimension in the main DP kernel.
 * Must be >= 1.  It controls how many rows of a given column are processed
 * together.  The default is chosen conservatively; it can be adjusted to
 * better match a particular machine's cache hierarchy.
 */
#ifndef NUSSINOV_I_BLOCK_SIZE
#define NUSSINOV_I_BLOCK_SIZE 64
#endif

/* Array initialization. */
static
void init_array (int n,
                 base POLYBENCH_1D(seq,N,n),
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j;

  // base is AGCT/0..3
  for (i = 0; i < n; i++) {
     seq[i] = (base)((i + 1) % 4);
  }

  for (i = 0; i < n; i++)
     for (j = 0; j < n; j++)
       table[i][j] = 0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
   Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
   with help from Allison Lake, Ting Zhou, and Tian Jin,
   based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
                                                    base POLYBENCH_1D(seq,N,n),
                                                    DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

  /* Use restrict-qualified local aliases to help the compiler with
     alias analysis and enable better optimization of the inner kernel. */
  base * __restrict__ seq_ = seq;
  DATA_TYPE (* __restrict__ table_)[n] = table;

  /* Row stride (in elements). Kept in a register and reused in the
     bifurcation loop to simplify pointer arithmetic. */
  const int stride = n;

#pragma scop
  /* Iterate over columns j from left to right, and within each column
     process rows i from bottom (i = j-1) to top (i = 0).  This order
     respects all dependencies:
       - (i, j-1), (i+1, j), (i+1, j-1),
       - (i, k)   for k < j,
       - (k+1, j) for k in [i+1, j-1].
   */
  for (j = 1; j < _PB_N; ++j) {

    /* Optional blocking in the i-dimension.  Column j is processed in
       blocks of NUSSINOV_I_BLOCK_SIZE consecutive rows to improve reuse
       of table_[*][j] and reduce cache conflict misses.  The block size
       is a tunable parameter. */
    for (int i_block_start = j - 1; i_block_start >= 0; i_block_start -= NUSSINOV_I_BLOCK_SIZE) {
      int i_block_end = i_block_start - NUSSINOV_I_BLOCK_SIZE + 1;
      if (i_block_end < 0)
        i_block_end = 0;

      for (i = i_block_start; i >= i_block_end; --i) {

        /* Start from the current cell value (initialized to 0 in init_array,
           but read here to preserve semantics if the table is ever pre-filled). */
        DATA_TYPE q = table_[i][j];

        /* Case 1: j remains unpaired; inherit from the left neighbor. */
        DATA_TYPE tmp = table_[i][j - 1];
        if (tmp > q)
          q = tmp;

        /* Case 2: i remains unpaired; inherit from the cell below. */
        tmp = table_[i + 1][j];
        if (tmp > q)
          q = tmp;

        /* Case 3: (i, j) form a pair, provided they are not adjacent.
           The base score is table_[i+1][j-1]; we add 1 if the bases match
           and i < j - 1.  When i == j - 1 we are not allowed to pair
           adjacent elements, so we simply propagate table_[i+1][j-1]. */
        tmp = table_[i + 1][j - 1];
        if (i < j - 1) {
          tmp += (DATA_TYPE)match(seq_[i], seq_[j]);
        }
        if (tmp > q)
          q = tmp;

        /* Case 4: bifurcation: split the interval (i, j) at every k with
           i < k < j, and combine the two sub-intervals (i, k) and (k+1, j).
           This is the most expensive part of the kernel (O(n^3) overall).
           It is written using explicit pointers to minimize index arithmetic
           inside the inner-most loop and to improve cache behavior. */
        if (i + 1 < j) {
          DATA_TYPE * __restrict__ row_i = table_[i];

          /* For k = i+1:
             - a points to table_[i][k]
             - b points to table_[k+1][j] = table_[i+1][j]
             After each iteration, a moves one element to the right within
             row i, and b jumps by 'stride' elements to the same column j
             in the next row. */
          DATA_TYPE *a = row_i + (i + 1);
          DATA_TYPE *b = &table_[i + 1][j];

          for (k = i + 1; k < j; ++k) {
            DATA_TYPE candidate = *a + *b;
            if (candidate > q)
              q = candidate;

            ++a;
            b += stride;
          }
        }

        /* Store the best score for subsequence (i, j). */
        table_[i][j] = q;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
