/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
   with help from Allison Lake, Ting Zhou, and Tian Jin,
   based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static void __attribute__((flatten, noinline))
kernel_nussinov(int n,
                base POLYBENCH_1D(seq,N,n),
	        DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

  /* Local pointer alias (helps the compiler with alias analysis).  */
  base *restrict s = seq;

#pragma scop
  /* NOTE: The original loop ran i from _PB_N-1 down to 0. For i = _PB_N-1
   * the inner j-loop is empty (since j starts from i+1), so no table
   * entries are computed in that iteration. We can safely start at
   * _PB_N-2 instead, which also guarantees that (i+1) is a valid row
   * index wherever it is used inside the loop.
   */
  for (i = _PB_N - 2; i >= 0; --i)
  {
    /* Cache row pointers to improve spatial locality and reduce the
     * cost of repeated 2D indexing.
     */
    DATA_TYPE *restrict row_i   = table[i];
    DATA_TYPE *restrict row_ip1 = table[i + 1];

    /* Cache the base at position i; used repeatedly for (i, j) matching. */
    const base si = s[i];

    for (j = i + 1; j < _PB_N; ++j)
    {
      /* We replace repeated "table[i][j] = max_score(table[i][j], ...)"
       * by an explicit accumulator variable 'best'. The table entry is
       * written only once at the end, which reduces memory traffic and
       * enables better optimization by the compiler.
       *
       * The table is initially zero-initialized, and each (i, j) pair
       * with j > i is computed exactly once, so starting from 0 here
       * is equivalent to the original semantics.
       */
      DATA_TYPE best = 0;

      /* Case 1: j unpaired to the left (take table[i][j-1]) and
       *         i unpaired below   (take table[i+1][j]).
       * The original code did:
       *   table[i][j] = max(table[i][j], table[i][j-1]);
       *   table[i][j] = max(table[i][j], table[i+1][j]);
       * We compute the same maximum directly.
       */
      DATA_TYPE v_left  = row_i[j - 1];
      DATA_TYPE v_down  = row_ip1[j];
      best = (v_left >= v_down) ? v_left : v_down;

      /* Case 2: possible base pair (i, j) via the diagonal (i+1, j-1).
       * Adjacent bases (j == i + 1) are not allowed to pair, matching
       * the original condition "if (i < j-1)".
       *
       * Original:
       *   if (i < j-1)
       *     table[i][j] = max(table[i][j],
       *                        table[i+1][j-1] + match(seq[i], seq[j]));
       *   else
       *     table[i][j] = max(table[i][j], table[i+1][j-1]);
       */
      DATA_TYPE diag = row_ip1[j - 1];
      if (j > i + 1) { /* i < j-1: non-adjacent -> pairing allowed */
        diag += (DATA_TYPE)match(si, s[j]);
      }
      if (diag > best)
        best = diag;

      /* Case 3: bifurcation at some k, i < k < j
       *   table[i][j] = max(table[i][j],
       *                      table[i][k] + table[k+1][j]);
       *
       * We keep the same order of traversal in k but operate on the
       * cached row pointer to reduce 2D index computations.
       */
      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = row_i[k] + table[k + 1][j];
        if (cand > best)
          best = cand;
      }

      /* Final result for this cell. */
      row_i[j] = best;
    }
  }
#pragma endscop

  (void)n; /* n is kept for interface compatibility; silences unused warning. */
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
