           - i <= NN-len-1 <= NN-2                 => i+1 < NN
         so the boundary checks present in the original code
         are provably always true and can be removed. */
      DATA_TYPE v_left = ti[j - 1];  /* table[i][j-1]   */
      DATA_TYPE v_down = ti1[j];     /* table[i+1][j]   */
      best = (v_left >= v_down) ? v_left : v_down;

      /* Case 2: i paired with j, with the constraint that
         adjacent bases are not allowed to pair.

         In the original code this was expressed as:
           if (i < j-1)
             table[i][j] = max(table[i][j],
                               table[i+1][j-1] + match(seq[i], seq[j]));
           else
             table[i][j] = max(table[i][j], table[i+1][j-1]);

         Since len == j - i, the condition (i < j-1) is
         equivalent to (len > 1).  The 'match' macro returns
         0 or 1, so masking it with (len > 1) yields a
         branchless form that is numerically equivalent. */
      int pair = (len > 1) & match(s[i], s[j]);
      DATA_TYPE v_pair = t[i + 1][j - 1] + pair;
      if (v_pair > best)
        best = v_pair;

      /* Case 3: bifurcation at position k, for i < k < j.
         We consider all possible splits (i..k) and (k+1..j)
         and keep the maximum.  Using 'ti' (row i) and the
         2D array 't' directly keeps the code simple while
         still giving the compiler opportunities to optimize
         address calculations. */
      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = ti[k] + t[k + 1][j];
        if (cand > best)
          best = cand;
      }

      /* Write final result for this subsequence. */
      ti[j] = best;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
