 *
 * Optimizations compared to the baseline PolyBench version:
 *
 *  - The DP is evaluated by increasing subsequence length (distance from the
 *    main diagonal) instead of descending i / ascending j. This diagonal
 *    traversal preserves the original dependences but improves data locality.
 *
 *  - We accumulate into a local "best" variable instead of repeatedly
 *    reading/writing table[i][j]. This reduces memory traffic and allows
 *    better optimization by the compiler.
 *
 *  - Redundant boundary checks are removed: with the (length, i) traversal,
 *    indices i+1, j-1, and j are always in range for all iterations.
 *
 *  - We use local, restrict-qualified pointers (seq_local, table_local,
 *    table_i) to give the compiler stronger aliasing information and reduce
 *    address computation overhead.
 *
 *  - Optional OpenMP parallelization over i for each fixed subsequence length
 *    is provided. It is only activated when compiled with -fopenmp and can be
 *    tuned via NUSSINOV_OMP_MIN_N. Without OpenMP, the pragmas are ignored
 *    and the code remains purely sequential.
 *
 * Semantics are preserved: each (i,j) with i < j is computed exactly once,
 * using exactly the same recurrence as in the original kernel.
 */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void __attribute__((flatten, noinline))
kernel_nussinov (int n,
                 base      POLYBENCH_1D(seq,N,n),
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Use the PolyBench run-time bound, as in the original code. */
  const int N_pb = _PB_N;

  /* Local restrict-qualified aliases improve the compiler's ability
   * to optimize memory accesses (no aliasing between seq and table). */
  base *restrict seq_local = seq;
  DATA_TYPE (*restrict table_local)[N] = table;

#pragma scop
  /* Process subsequences in order of increasing length (distance from
   * the main diagonal). For each fixed length, (i,j=i+len) cells are
   * independent of each other and can be computed in parallel. */
  for (int len = 1; len < N_pb; ++len)
  {
    const int i_max = N_pb - len;

    /* Optional OpenMP parallelization (ignored if not compiled with -fopenmp).
     * Cells with the same subsequence length "len" have no dependences between
     * different i values: they only depend on entries with strictly smaller
     * lengths, which have already been computed in previous iterations of len. */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) if (N_pb >= NUSSINOV_OMP_MIN_N)
#endif
    for (int i = 0; i < i_max; ++i)
    {
      const int j = i + len;

      /* Row pointer for faster access and better cache locality. */
      DATA_TYPE *restrict table_i = table_local[i];

      /* Start from the case where j is unpaired:
       * best = table[i][j-1].
       *
       * Note: All DP values are non-negative (they are built from 0 and
       * additions of 0 or 1), so omitting an explicit comparison with 0
       * keeps the semantics identical to the original code. */
      DATA_TYPE best = table_i[j - 1];

      /* Case: i is unpaired -> table[i+1][j]. */
      DATA_TYPE v = table_local[i + 1][j];
      if (v > best)
        best = v;

      /* Case: potential pairing between i and j (never allowed for adjacent
       * bases). In the original code:
       *
       *   if (i < j-1)
       *     table[i][j] = max(table[i][j], table[i+1][j-1] + match(seq[i],seq[j]));
       *   else
       *     table[i][j] = max(table[i][j], table[i+1][j-1]);
       *
       * len == j-i, so (i < j-1) <=> (len > 1).
       */
      v = table_local[i + 1][j - 1];
      if (len > 1)
      {
        /* Non-adjacent: allow bonding between i and j, adding 0 or 1. */
        v += (DATA_TYPE)match(seq_local[i], seq_local[j]);
      }
      /* len == 1 falls back to table[i+1][j-1] alone, as in the original. */
      if (v > best)
        best = v;

      /* Case: bifurcation of the interval (i,j) into (i,k) and (k+1,j).
       * This corresponds exactly to the original loop:
       *
       *   for (k=i+1; k<j; k++)
       *     table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
       */
      for (int k = i + 1; k < j; ++k)
      {
        DATA_TYPE candidate = table_i[k] + table_local[k + 1][j];
        if (candidate > best)
          best = candidate;
      }

      /* Write back the best score for subsequence [i, j]. */
      table_i[j] = best;
    }
  }
#pragma endscop
}


